import re
import unicodedata

# Exact normalized titles plus substantial delimiter-separated title fragments.
def exact_title_fragments(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", s or "").casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        return " ".join(re.findall(r"[^\W_]+", s, re.UNICODE))

    title = r.get("title", "")
    keys = []
    full = norm(title)
    if full:
        keys.append("xt:" + full)
    for part in re.split(r"\s*(?:\||[–—]|\s-\s|/)\s*", title):
        p = norm(part)
        if len(p) >= 12 and len(p.split()) >= 2:
            keys.append("xp:" + p)
    return list(dict.fromkeys(keys))[:4]


# Exact and separator-tolerant model, part-number, measurement, and numeric identifiers.
def identifier_keys(r):
    def fold(s):
        s = unicodedata.normalize("NFKD", s or "").casefold()
        return "".join(c for c in s if not unicodedata.combining(c))

    text = " ".join(r.get(a, "") for a in ("title", "brand", "description"))
    text = fold(text)
    candidates = re.findall(
        r"(?<!\w)(?:[a-z]+\d[\w./+-]*|\d+[a-z][\w./+-]*|\d{3,}(?:[-./]\w+)+|\d{5,})(?!\w)",
        text,
    )
    keys = []
    for raw in candidates:
        canonical = re.sub(r"[^a-z0-9]", "", raw)
        if len(canonical) < 4:
            continue
        keys.append("id:" + canonical)
        if any(c.isalpha() for c in canonical) and any(c.isdigit() for c in canonical):
            split = re.sub(r"(?<=\D)(?=\d)|(?<=\d)(?=\D)", ":", canonical)
            keys.append("is:" + split)
            letters = re.sub(r"\d+", "#", canonical)
            digits = re.sub(r"[a-z]+", "", canonical)
            if len(digits) >= 3:
                keys.append("if:" + letters[:10] + ":" + digits[-6:])
    return list(dict.fromkeys(keys))[:10]


# Distinctive lexical anchors from title, brand, and description, tolerant of compounds and inflection.
def lexical_anchor_keys(r):
    def tokens(s):
        s = unicodedata.normalize("NFKD", s or "").casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        return re.findall(r"[^\W_]+", s, re.UNICODE)

    stop = {
        "with", "from", "this", "that", "your", "online", "shop", "store",
        "site", "page", "product", "products", "item", "items", "women",
        "woman", "mens", "men", "ladies", "sale", "black", "white", "blue",
        "green", "size", "colour", "color", "made", "available", "equipment",
        "supplies", "accessories", "apparel", "clothing", "description",
        "details", "model", "series", "example", "official", "regular",
    }
    title_brand = tokens(r.get("title", "") + " " + r.get("brand", ""))
    desc = tokens(r.get("description", ""))
    pool = title_brand + [t for t in desc if len(t) >= 6]
    pool = [t for t in pool if len(t) >= 4 and t not in stop and not t.isdigit()]
    ranked = sorted(set(pool), key=lambda t: (-len(t), t))
    keys = []
    for t in ranked[:10]:
        keys.append("tk:" + t)
        if len(t) >= 7:
            stem = re.sub(r"(?:ing|ments?|ness|ation|ions?|ers?|es|s)$", "", t)
            if len(stem) >= 5:
                keys.append("ts:" + stem)
    return list(dict.fromkeys(keys))[:14]


# Character-level consonant signatures plus broad fallbacks for records lacking reliable metadata.
def fuzzy_and_sparse_keys(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", s or "").casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        return " ".join(re.findall(r"[^\W_]+", s, re.UNICODE))

    title = norm(r.get("title", ""))
    words = [w for w in title.split() if len(w) >= 5]
    keys = []
    for w in sorted(set(words), key=lambda x: (-len(x), x))[:8]:
        latin = re.sub(r"[^a-z0-9]", "", w)
        if len(latin) < 5:
            continue
        skeleton = latin[0] + re.sub(r"[aeiouy]", "", latin[1:])
        skeleton = re.sub(r"(.)\1+", r"\1", skeleton)
        if len(skeleton) >= 4:
            keys.append("cs:" + skeleton[:7])
        keys.append("ce:" + latin[:3] + ":" + latin[-3:])

    brand = norm(r.get("brand", ""))
    price = norm(r.get("price", ""))
    desc = norm(r.get("description", ""))
    if title and not brand and not price:
        n = len(title)
        keys.extend(("ml:" + str(n // 24), "ms:" + str((n + 12) // 24)))
    if title and not brand and not price and not desc:
        toks = title.split()
        if toks and all(not any(c.isdigit() for c in t) for t in toks):
            keys.append("fb:bare-alpha")
    return list(dict.fromkeys(keys))[:12]


SCHEMES = {
    "exact_title_fragments": exact_title_fragments,
    "identifier_keys": identifier_keys,
    "lexical_anchor_keys": lexical_anchor_keys,
    "fuzzy_and_sparse_keys": fuzzy_and_sparse_keys,
}
